action.command:
cd /workspace && python3 - <<'EOF'
import re, os
missing = []
for root, dirs, files in os.walk('resources'):
    for f in files:
        if f.endswith(('.vue','.ts','.tsx')):
            p = os.path.join(root,f)
            src = open(p, encoding='utf-8').read()
            for m in re.finditer(r'''from\s+['"](@/|\./|\.\./)([^'"]+)['"]''', src):
                base, spec = m.group(1), m.group(2)
                target = 'resources/js/' + spec if base=='@/' else os.path.normpath(os.path.join(os.path.dirname(p), spec))
                candidates = [target, target+'.vue', target+'.ts', target+'.tsx', target+'.js', os.path.join(target,'index.ts'), os.path.join(target,'index.vue')]
                if not any(os.path.exists(c) for c in candidates):
                    missing.append((p, base+spec))
for p, s in sorted(set(missing)):
    print(p, '->', s)
print("TOTAL missing:", len(set(missing)))
EOF

